"""Bundle generated files into one zip archive.

The archive keeps the folder layout the CLI writes and adds a README.md that
lists what each file is, so a caller such as cloudbust can hand a user one
download.
"""

import io
import posixpath
import zipfile
from typing import Iterable, Mapping, Union

from bust._version import __VERSION__

README_NAME = "README.md"

# Fixed so the same files always give the same zip bytes.
_ZIP_DATE_TIME = (1980, 1, 1, 0, 0, 0)

# Checked in order, so the longer suffixes come before the ones they end with.
_SUFFIX_DESCRIPTIONS = (
    (
        "_localbus_pkg.vhd",
        "Local-bus types shared by the register file and the endpoint.",
    ),
    ("_regfile_pkg.vhd", "Register types, addresses and reset values."),
    ("_regfile.vhd", "Register file."),
    ("_endpoint.vhd", "Bus endpoint that connects the bus to the register file."),
    ("_tb.vhd", "Self-checking UVVM testbench."),
    (".vhd", "Starter top level. It is yours to edit."),
    (".h", "C header."),
    (".hpp", "C++ header."),
    (".py", "Python header."),
    (".xml", "IPBus address table."),
    (".tex", "LaTeX documentation."),
    (".pdf", "PDF documentation."),
    (".html", "HTML documentation."),
    (".md", "Markdown documentation."),
)


def describe_file(path: str) -> str:
    """Return a one-line description of a generated file, or "" if unknown."""
    filename = posixpath.basename(path)
    for suffix, description in _SUFFIX_DESCRIPTIONS:
        if filename.endswith(suffix):
            return description
    return ""


def build_readme(paths: Iterable[str]) -> str:
    """Return a README.md that lists each of `paths` with what it is."""
    rows = "".join(f"| `{path}` | {describe_file(path)} |\n" for path in sorted(paths))
    return (
        "# Generated files\n"
        "\n"
        f"Generated by bust {__VERSION__}.\n"
        "\n"
        "| File | What it is |\n"
        "| --- | --- |\n"
        f"{rows}"
    )


def bundle_zip(files: Mapping[str, Union[str, bytes]]) -> bytes:
    """Return a zip of `files` with a README.md at its root.

    Args:
        files: Generated files as {path: content}, such as the result of
            `generate_files`, with paths relative to the output directory and
            separated by "/". Text is encoded as UTF-8.

    Raises:
        ValueError: If `files` already has a README.md at its root.
    """
    if README_NAME in files:
        raise ValueError(f"{README_NAME} is reserved for the file list")
    archive = io.BytesIO()
    with zipfile.ZipFile(archive, "w") as zip_file:
        _add_entry(zip_file, README_NAME, build_readme(files))
        for path in sorted(files):
            _add_entry(zip_file, path, files[path])
    return archive.getvalue()


def _add_entry(zip_file: zipfile.ZipFile, path: str, content: Union[str, bytes]):
    entry = zipfile.ZipInfo(path, date_time=_ZIP_DATE_TIME)
    entry.compress_type = zipfile.ZIP_DEFLATED
    entry.external_attr = 0o644 << 16
    zip_file.writestr(entry, content)
